import{_ as i,o as n,c as t,ai as o}from"./chunks/framework.Bzm6MoPr.js";const x=JSON.parse('{"title":"Execution Context","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/js/execution-context.md","filePath":"frontend/js/execution-context.md"}'),a={name:"frontend/js/execution-context.md"};function l(s,e,r,c,d,u){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="execution-context" tabindex="-1">Execution Context <a class="header-anchor" href="#execution-context" aria-label="Permalink to “Execution Context”">​</a></h1><ul><li><strong><em>Execution Context.</em></strong></li><li>Execution Context has 2 components <ol><li>Memory Component (Variable Enviroment) - variable and function stored as key-value pairs.</li><li>Code Component (Thread of Execution) - js code is executed here.</li></ol></li></ul><h2 id="how-js-code-is-executed-by-js-engine" tabindex="-1">How JS code is executed by JS Engine <a class="header-anchor" href="#how-js-code-is-executed-by-js-engine" aria-label="Permalink to “How JS code is executed by JS Engine”">​</a></h2><ul><li>When you run a JS code, Global execution context is created.</li><li>This Global Execution Context is created in 2 phases <ol><li>Memory Creation Phase - Allocates memory to variables and functions. <ul><li>variables - assigned <code>undefined</code></li><li>functions - whole function code is assigned</li></ul></li><li>Code Execution Phase - actual values are assigned to variables and functions are invoked.</li></ol></li><li>Each function invocation creates a new Execution Context and with return statement that execution context is destroyed.</li></ul><h2 id="call-stack" tabindex="-1">Call Stack <a class="header-anchor" href="#call-stack" aria-label="Permalink to “Call Stack”">​</a></h2><ul><li>Maintains the Order of Execution for Execution Contexts.</li><li>Manages Global Execution Context and child execution context.</li><li>Global Execution Context &lt;= EC1 &lt;= EC2 (top-of-stack)</li><li>Also known as <ul><li>Call Stack</li><li>Execution Context Stack</li><li>Program Stack</li><li>Control Stack</li><li>Runtime Stack</li><li>Machine Stack</li></ul></li></ul><h2 id="hoisting" tabindex="-1">Hoisting <a class="header-anchor" href="#hoisting" aria-label="Permalink to “Hoisting”">​</a></h2><ul><li>All the variables and functions defined in the js are created during memory allocation phase. <ul><li>vars as undefined</li><li>functions as copied code block</li></ul></li><li>Functions defines as arrow function or var are allocated as if they are vars ie. undefined.</li></ul><h3 id="not-defined-vs-undefined" tabindex="-1">not-defined vs undefined <a class="header-anchor" href="#not-defined-vs-undefined" aria-label="Permalink to “not-defined vs undefined”">​</a></h3><ul><li><strong>not defined</strong> - means variable/function was not defined in Memory Creation Phase</li><li><strong>undefined</strong> - means variable/function was defined in Memory Creation phase but value is not assigned.</li></ul><h2 id="shortest-js-program" tabindex="-1">Shortest JS Program <a class="header-anchor" href="#shortest-js-program" aria-label="Permalink to “Shortest JS Program”">​</a></h2><ul><li>Empty js file is the shortest js program.</li><li>JS Engine creates the following <ul><li>Global Execution Context</li><li>Global Object - <code>window</code> for browsers</li><li>this - pointed to window</li></ul></li><li>same : <code>this.a</code> , <code>window.a</code>, <code>a</code></li></ul>',12)])])}const f=i(a,[["render",l]]);export{x as __pageData,f as default};
